@@ -0,0 +1,12 @@
+import { createEventCard } from "./event-card.js";
+
+export function sortByStart(events, project = (event) => event) {
+  return events
+    .map((event) => ({ value: project(event), time: new Date(event.startsAt).getTime() }))
+    .sort((a, b) => a.time - b.time)
+    .map(({ value }) => value);
+}
+
+export function buildAgenda(events) {
+  return sortByStart(events, createEventCard);
+}

